#!/bin/bash # Subconverter CI 监控 + SSH 远程更新脚本 # 功能：git push → 轮询 Actions → SSH 执行 docker compose up -d set -e # ========== 配置区 ========== REPO="whua898/subconverter" SSH_HOST="user@vps-ip" SSH_KEY="$HOME/.ssh/id_rsa" REMOTE_COMPOSE_DIR="/path/to/subconverter" # VPS 上 docker-compose.yml 目录 POLL_INTERVAL=30 # 轮询间隔（秒） MAX_TIMEOUT=900 # 最大等待时间（秒），15分钟 # ========== 日志函数 ========== log_info() { echo "[INFO] $(date '+%H:%M:%S') $*"; } log_success() { echo "[OK] $(date '+%H:%M:%S') $*"; } log_error() { echo "[ERROR] $(date '+%H:%M:%S') $*" >&2; } # ========== 主流程 ========== main() { local start_time=$(date +%s) local commit_msg="fix: 自动修复 $(date '+%Y%m%d-%H%M%S')" log_info "=== CI 远程更新流程开始 ===" log_info "仓库: $REPO" log_info "目标主机: $SSH_HOST" log_info "远程目录: $REMOTE_COMPOSE_DIR" # 1. Git 操作 log_info "[1/4] Git 提交并推送..." git add . git commit -m "$commit_msg" || log_info "无新变更，跳过 commit" git push origin HEAD:main log_success "推送完成: $commit_msg" # 2. 等待 Actions 启动 log_info "[2/4] 等待 GitHub Actions 启动..." sleep 10 # 3. 轮询编译状态 log_info "[3/4] 轮询编译状态（每 ${POLL_INTERVAL}s）..." while true; do local now=$(date +%s) local elapsed=$((now - start_time)) if [ $elapsed -gt $MAX_TIMEOUT ]; then log_error "编译超时（${MAX_TIMEOUT}s），退出" exit 1 fi # 获取最新 workflow run local run_id=$(gh run list --repo "$REPO" --limit 1 --json databaseId --jq '.[0].databaseId') if [ -z "$run_id" ]; then log_error "无法获取 run_id" exit 1 fi local status=$(gh run view "$run_id" --repo "$REPO" --json status --jq '.status') local conclusion=$(gh run view "$run_id" --repo "$REPO" --json conclusion --jq '.conclusion // ""') log_info "Run #$run_id 状态: $status | 结论: $conclusion" case "$status" in "completed") if [ "$conclusion" = "success" ]; then log_success "编译成功！" break else log_error "编译失败: $conclusion" # 可选：拉取日志分析原因 gh run view "$run_id" --repo "$REPO" --log-failed exit 1 fi ;; "in_progress"|"queued") log_info "编译中... (${elapsed}s)" sleep "$POLL_INTERVAL" ;; *) log_error "未知状态: $status" sleep "$POLL_INTERVAL" ;; esac done # 4. SSH 远程更新 log_info "[4/4] SSH 远程更新容器..." ssh -i "$SSH_KEY" "$SSH_HOST" "cd $REMOTE_COMPOSE_DIR && docker compose pull && docker compose up -d --force-recreate" log_success "远程更新完成" # 等待服务启动 sleep 5 # 验证服务状态 local health=$(ssh -i "$SSH_KEY" "$SSH_HOST" "curl -s -o /dev/null -w '%{http_code}' http://localhost:8080/" || echo "000") if [ "$health" = "200" ]; then log_success "✓ 服务健康检查通过 (HTTP $health)" else log_error "✗ 服务异常 (HTTP $health)" exit 1 fi log_info "=== 全流程完成 ===" } main "$@"